#include "../models/film_native_contact/CoupledPlaneStep.h"
#include <iostream>
using namespace regrip_film_native;
int main(){try{Assembly m(5);std::vector<Point>q(m.size()),v(m.size()),J(m.size());J[m.id(0,4,2)][2]=1;CoupledPlaneStep solver(m,m.masses(),.005,2,.0001,q,v,J,0);auto y=solver.pack(v);for(int i=0;i<y.size();++i)y(i)=1e-4*std::sin(i);auto e=solver.evaluate(y);double ge=0,he=0;
 for(unsigned k:{3*m.id(0,2,2)+2,3*m.id(1,2,0)+2}){int column=solver.index[k];double step=1e-4;auto plus=y,minus=y;plus(column)+=step;minus(column)-=step;auto p=solver.evaluate(plus),n=solver.evaluate(minus);ge=std::max(ge,std::abs((p.phi-n.phi)/(2*step)-e.gradient(column)));he=std::max(he,((p.gradient-n.gradient)/(2*step)-e.tangent.col(column)).cwiseAbs().maxCoeff());}
 if(ge>1e-10||he>1e-8)throw std::runtime_error("coupled projected potential/gradient/Hessian FD");std::cout<<"FD gradient="<<ge<<" Hessian="<<he<<'\n';auto incoming=v;incoming[m.id(0,4,2)][2]=-1;CoupledPlaneStep active(m,m.masses(),.005,2,.0001,q,incoming,J,0);auto result=active.solve(v,0);if(result.lambda<0||std::abs(result.gap)>1e-10||result.residual>1e-12)throw std::runtime_error("coupled plane equilibrium");std::cout<<"PASS projected BE potential/gradient/Hessian FD "<<ge<<' '<<he<<";lambda="<<result.lambda<<" residual="<<result.residual<<";not general contact qualification\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
